-- Insert Attribute Testing module template
-- 2 targets, criteria up to 5 (per design: docs/implicitAssociation1.png)
INSERT INTO module_templates (name, description, structure, stage_template_id, display_order, is_active)
VALUES (
  'Attribute Testing',
  'Implicit association test with 2 targets and attribute classification (up to 5 criteria)',
  '{"components":[{"id":"target-1-name","type":"input","label":"Name of the object","placeholder":{"enabled":true,"text":"Text the name here"},"required":true,"order":1,"settings":{"groupLabel":"Target 1","description":"You can use an image or a name for this."}},{"id":"target-1-image","type":"file-upload","label":"Target 1 Image","order":2,"settings":{"groupLabel":"Target 1"},"fileUpload":{"maxSizeMB":5,"acceptedFormats":["image/jpeg","image/png","image/gif"]}},{"id":"target-2-name","type":"input","label":"Name of the object","placeholder":{"enabled":true,"text":"Text the name here"},"required":true,"order":3,"settings":{"groupLabel":"Target 2","description":"You can use an image or a name for this."}},{"id":"target-2-image","type":"file-upload","label":"Target 2 Image","order":4,"settings":{"groupLabel":"Target 2"},"fileUpload":{"maxSizeMB":5,"acceptedFormats":["image/jpeg","image/png","image/gif"]}},{"id":"priming-time","type":"select","label":"Priming display time","value":"400","options":[{"label":"300 ms","value":"300"},{"label":"400 ms","value":"400"},{"label":"500 ms","value":"500"}],"order":5},{"id":"criteria","type":"ranking-list","label":"Criteria","required":true,"order":6,"settings":{"minItems":1,"maxItems":5,"hasImage":true}},{"id":"show-results","type":"checkbox","label":"Show results to respondents","value":"false","order":7},{"id":"exercise-instructions","type":"textarea","label":"Exercise instructions","placeholder":{"enabled":true,"text":"One of the objects appears each trial. Use the keyboard or on-screen buttons: left arrow for the first category, right arrow for the second. If you make an occasional mistake, you will see X; correct your answer rapidly. Classify items as quickly as you can, but also be accurate."},"order":8,"settings":{"maxLength":500}},{"id":"test-instructions","type":"textarea","label":"Test instructions","placeholder":{"enabled":true,"text":"Now a word or image may appear before each object; ignore it. Classify as quickly as possible: left arrow for the first category, right arrow for the second."},"order":9,"settings":{"maxLength":500}}]}',
  (SELECT id FROM stage_templates WHERE name = 'Implicit Association'),
  0,
  1
);

-- Insert Comparing Attribute module template
-- 3 objects + dimension-1/dimension-2 + criteria up to 15 (per design: docs/implicitAssociation3.png)
INSERT INTO module_templates (name, description, structure, stage_template_id, display_order, is_active)
VALUES (
  'Comparing Attribute',
  'Implicit association test comparing up to 3 objects across 2 named dimensions',
  '{"components":[{"id":"object-1-name","type":"input","label":"Name of the object","placeholder":{"enabled":true,"text":"Text the name here"},"required":true,"order":1,"settings":{"groupLabel":"Object 1","description":"You can use an image or a name for this."}},{"id":"object-1-image","type":"file-upload","label":"Object 1 Image","order":2,"settings":{"groupLabel":"Object 1"},"fileUpload":{"maxSizeMB":5,"acceptedFormats":["image/jpeg","image/png","image/gif"]}},{"id":"object-2-name","type":"input","label":"Name of the object","placeholder":{"enabled":true,"text":"Text the name here"},"required":true,"order":3,"settings":{"groupLabel":"Object 2","description":"You can use an image or a name for this."}},{"id":"object-2-image","type":"file-upload","label":"Object 2 Image","order":4,"settings":{"groupLabel":"Object 2"},"fileUpload":{"maxSizeMB":5,"acceptedFormats":["image/jpeg","image/png","image/gif"]}},{"id":"object-3-name","type":"input","label":"Name of the object","placeholder":{"enabled":true,"text":"Text the name here"},"required":false,"order":5,"settings":{"groupLabel":"Object 3","description":"You can use an image or a name for this."}},{"id":"object-3-image","type":"file-upload","label":"Object 3 Image","order":6,"settings":{"groupLabel":"Object 3"},"fileUpload":{"maxSizeMB":5,"acceptedFormats":["image/jpeg","image/png","image/gif"]}},{"id":"dimension-1","type":"input","label":"Dimension 1","placeholder":{"enabled":true,"text":"YES"},"required":true,"order":7},{"id":"dimension-2","type":"input","label":"Dimension 2","placeholder":{"enabled":true,"text":"NO"},"required":true,"order":8},{"id":"priming-time","type":"select","label":"Priming display time","value":"400","options":[{"label":"300 ms","value":"300"},{"label":"400 ms","value":"400"},{"label":"500 ms","value":"500"}],"order":9},{"id":"criteria","type":"ranking-list","label":"Criteria","required":true,"order":10,"settings":{"minItems":1,"maxItems":15,"hasImage":true}},{"id":"show-results","type":"checkbox","label":"Show results to respondents","value":"false","order":11},{"id":"exercise-instructions","type":"textarea","label":"Exercise instructions","placeholder":{"enabled":true,"text":"In this task, different objects will appear. Use the keyboard for this exercise if you take the test on a PC, tablet, or laptop. Press the left arrow key if [[Object 1]] appears. And press the right arrow key if you see [[Object 2]]. If you make an occasional mistake, you will see X; correct your answer rapidly. Classify items as quickly as you can, but also be accurate."},"order":12,"settings":{"maxLength":500}},{"id":"test-instructions","type":"textarea","label":"Test instructions","placeholder":{"enabled":true,"text":"Now you will see a word or image before each object. Try to ignore this. Your task is the same: identify objects as quickly as possible. Use the keyboard for this exercise if you take the test on a PC, tablet, or laptop."},"order":13,"settings":{"maxLength":500}}]}',
  (SELECT id FROM stage_templates WHERE name = 'Implicit Association'),
  1,
  1
);

